// One output item per PDF attachment, with the file in binary field "data".
const out = [];
for (const item of $input.all()) {
  for (const [key, file] of Object.entries(item.binary ?? {})) {
    const isPdf = file.mimeType === 'application/pdf' || /\.pdf$/i.test(file.fileName || '');
    if (!isPdf) continue;
    out.push({
      json: {
        source: 'email',
        sourceRef: item.json.id,
        from: item.json.from?.value?.[0]?.address || '',
        subject: item.json.subject || '',
        fileName: file.fileName || key + '.pdf',
      },
      binary: { data: file },
    });
  }
}
return out;

// Same shape as the email path: metadata in json, PDF in binary "data".
return {
  json: { source: 'drive', sourceRef: $json.id, from: '', subject: '', fileName: $json.name || 'invoice.pdf' },
  binary: $input.item.binary,
};

// Deterministic checks on the AI's extraction. Anything odd -> status "review" with reasons.
const APPROVAL_LIMIT = 5000;                          // SET ME: totals above this need approval
const CURRENCIES = ['USD', 'EUR', 'GBP', 'IDR', 'SGD', 'AUD']; // SET ME: currencies you accept
const TOLERANCE = 0.02;                               // rounding tolerance per check
const src = $('Readable Text?').item.json;
const x = $json.output ?? {};
const n = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v));
const r2 = (v) => (v === null ? null : Math.round(v * 100) / 100);
const anomalies = [];

for (const f of ['vendorName', 'invoiceNumber', 'invoiceDate', 'total']) if (x[f] === null || x[f] === undefined || x[f] === '') anomalies.push('missing ' + f);
const items = Array.isArray(x.lineItems) ? x.lineItems : [];
const lineSum = r2(items.reduce((s, li) => s + (n(li.amount) ?? 0), 0));
const subtotal = n(x.subtotal), tax = n(x.tax) ?? 0, shipping = n(x.shipping) ?? 0, discount = n(x.discount) ?? 0, total = n(x.total);
if (items.length && subtotal !== null && Math.abs(lineSum - subtotal) > TOLERANCE) anomalies.push(`line items (${lineSum}) ≠ subtotal (${subtotal})`);
if (subtotal !== null && total !== null && Math.abs(subtotal + tax + shipping - discount - total) > TOLERANCE) anomalies.push(`subtotal + tax + shipping − discount ≠ total (${total})`);
if (total !== null && total <= 0) anomalies.push('total is zero or negative');
if (total !== null && total > APPROVAL_LIMIT) anomalies.push(`over approval limit (${APPROVAL_LIMIT})`);
if (x.currency && !CURRENCIES.includes(String(x.currency).toUpperCase())) anomalies.push('unexpected currency ' + x.currency);
if (x.vendorApproved !== true) anomalies.push('vendor not in approved list');
if (x.duplicateFound === true) anomalies.push('possible duplicate invoice number');
const today = new Date().toISOString().slice(0, 10);
if (x.invoiceDate && x.invoiceDate > today) anomalies.push('invoice date is in the future');
if (x.invoiceDate && x.dueDate && x.dueDate < x.invoiceDate) anomalies.push('due date before invoice date');
if (n(x.confidence) !== null && n(x.confidence) < 0.7) anomalies.push('low AI confidence');

return { json: {
  processedAt: new Date().toISOString(),
  source: src.source, fileName: src.fileName,
  vendorName: x.vendorName ?? '', vendorApproved: x.vendorApproved === true,
  invoiceNumber: x.invoiceNumber ?? '', invoiceDate: x.invoiceDate ?? '', dueDate: x.dueDate ?? '',
  currency: (x.currency ?? '').toUpperCase(),
  subtotal: subtotal ?? '', tax, total: total ?? '',
  lineItemCount: items.length,
  lineItems: items.map((li) => `${li.quantity ?? 1} × ${li.description} = ${li.amount}`).join(' | ').slice(0, 1000),
  status: anomalies.length ? 'review' : 'ok',
  anomalies: anomalies.join('; '),
  confidence: n(x.confidence) ?? '',
} };

